finding_cards = ''.join(f'''<details class="finding" data-priority="{f['priority']}"><summary><span class="priority {f['priority']}">{f['priority']}</span><strong>{f['id']} · {esc(f['title'])}</strong><span class="kind">{esc(f['kind'])}</span></summary><div class="finding-content">{''.join(f'<p><b>{label}</b> {esc(f[key])}</p>' for label,key in [('Факт.','actual'),('Ожидание.','expected'),('Воспроизведение.','steps'),('Риск для игры.','impact'),('Исправление.','fix')])}<p class="source">Код: {esc(f['source'])} · <a href="{esc(f['evidence'])}">Доказательство</a></p></div></details>''' for f in findings)

